import './app.js';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const storage={get(key){try{return localStorage.getItem(key);}catch{return null;}},set(key,value){try{localStorage.setItem(key,value);return true;}catch{return false;}}};
let lang=document.documentElement.lang,paused=document.body.classList.contains('motion-paused'),era='1946',poster='gold';
const words=(fr,ar)=>lang==='ar'?ar:fr;
const node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const worlds=new Map(),jerseys=[];
const entranceObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('entered');entranceObserver.unobserve(e.target);}}),{threshold:.08});
$$('.section-title,.explore-tile,.city-copy,.collection-card,.values-grid article,.journal-card,.steps article').forEach((el,i)=>{el.classList.add('scroll-entrance');el.style.setProperty('--entrance-delay',`${i%3*65}ms`);entranceObserver.observe(el);});
function translate(){lang=document.documentElement.lang;$$('[data-fr][data-ar]').forEach(n=>{n.textContent=n.dataset[lang];});const titles={'index.html':'الرئيسية','matchs.html':'مركز المباريات','club.html':'تاريخنا','collection.html':'التشكيلة','studio.html':'استوديو القميص','tribune.html':'المدرج'};document.title=lang==='ar'?`ديما ماص — ${titles[document.body.dataset.page]}`:`DIMA MAS — ${document.body.dataset.title}`;$$('[data-scene]').forEach(el=>{const labels={ball:['Ballon 3D : glisser ou utiliser les flèches.','كرة ثلاثية الأبعاد: اسحب أو استخدم الأسهم.'],stadium:['Stade 3D : glisser ou utiliser les flèches.','ملعب ثلاثي الأبعاد: اسحب أو استخدم الأسهم.'],trophy:['Trophée 3D : glisser ou utiliser les flèches.','كأس ثلاثي الأبعاد: اسحب أو استخدم الأسهم.'],flags:['Drapeaux 3D : glisser ou utiliser les flèches.','أعلام ثلاثية الأبعاد: اسحب أو استخدم الأسهم.']};const label=labels[el.dataset.scene][lang==='ar'?1:0];el.setAttribute('aria-label',label);el.querySelector('canvas')?.setAttribute('aria-label',label);});renderEra();if($('#fan-cards'))renderFans();if($('#players'))renderPlayers();}
document.addEventListener('dima:language',translate);
document.addEventListener('dima:motion',e=>{paused=e.detail;worlds.forEach(w=>w.setPaused(paused));jerseys.forEach(j=>j.setPaused(paused));});
$$('#main-nav a').forEach(a=>{if(a.dataset.page===document.body.dataset.page)a.setAttribute('aria-current','page');});

const sceneObserver=new IntersectionObserver(entries=>entries.forEach(async e=>{if(!e.isIntersecting)return;sceneObserver.unobserve(e.target);try{const {World}=await import('./experience.js');const w=new World(e.target,paused);worlds.set(e.target,w);if(w.kind==='stadium')w.setMode($('[data-stadium].active')?.dataset.stadium||'night');if(w.kind==='flags')w.wind=Number($('[data-wind].active')?.dataset.wind||1);}catch(error){console.warn('3D scene unavailable; keeping visual fallback.',error);}}),{rootMargin:'200px'});$$('[data-scene]').forEach(el=>sceneObserver.observe(el));
const jerseyObserver=new IntersectionObserver(entries=>entries.forEach(async e=>{if(!e.isIntersecting)return;jerseyObserver.unobserve(e.target);try{const {JerseyStudio}=await import('./jersey.js');const j=new JerseyStudio(e.target,{config:{kit:e.target.dataset.jersey,size:'M',name:'MASSAWI',number:'10'},paused});j.autoRotate=true;jerseys.push(j);}catch{e.target.append(node('span','scene-fallback','MAS'));}}),{rootMargin:'150px'});$$('[data-jersey]').forEach(el=>jerseyObserver.observe(el));

function selectButtons(selector,button){$$(selector).forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});}
$$('[data-stadium]').forEach(b=>b.addEventListener('click',()=>{selectButtons('[data-stadium]',b);worlds.forEach(w=>{if(w.kind==='stadium')w.setMode(b.dataset.stadium);});}));
$$('[data-wind]').forEach(b=>b.addEventListener('click',()=>{selectButtons('[data-wind]',b);worlds.forEach(w=>{if(w.kind==='flags'){w.wind=Number(b.dataset.wind);w.dirty=true;}});}));
$$('[data-tilt]').forEach(el=>{el.addEventListener('pointermove',e=>{if(paused||e.pointerType==='touch')return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(900px) rotateX(${-y*7}deg) rotateY(${x*7}deg) translateY(-5px)`;});el.addEventListener('pointerleave',()=>el.style.transform='');});

// Real URLs retain normal new-tab behavior, browser history and deep links.
let navigating=false;
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target||a.download||paused)return;const url=new URL(a.href);if(url.origin!==location.origin||!url.pathname.endsWith('.html')||url.pathname===location.pathname&&url.search===location.search||navigating)return;e.preventDefault();navigating=true;document.body.classList.add('is-leaving');setTimeout(()=>location.assign(url.href),260);});
addEventListener('pageshow',()=>{navigating=false;document.body.classList.remove('is-leaving');});

const eras={
  '1946':{number:'1946',fr:['UNE HISTOIRE\nQUI PREND RACINE.','Le Maghreb Association Sportive voit le jour à Fès en 1946. La ville et le club partagent depuis un même fil : celui de l’appartenance. Source : guide CAF de Fès, lié ci-dessus.'],ar:['حكاية\nتضرب جذورها.','تأسّس المغرب الرياضي الفاسي بفاس سنة 1946. منذ ذلك الحين يجمع المدينة والنادي خيط واحد: الانتماء. المصدر: دليل الكاف لفاس المرتبط أعلاه.']},
  '2011':{number:'2011',fr:['UN CHAPITRE\nÀ L’ÉCHELLE AFRICAINE.','En 2011, le MAS remporte la Coupe de la Confédération de la CAF. Ce titre inscrit le club au palmarès continental. Consulte la source FFF dans la section suivante.'],ar:['صفحة\nعلى المستوى الإفريقي.','سنة 2011، أحرز الماص كأس الكونفدرالية الإفريقية، ليدوّن اسمه في سجل الأبطال. تجد مصدر الاتحاد الفرنسي في القسم التالي.']},
  future:{number:'∞',fr:['LA SUITE\nS’ÉCRIT ENSEMBLE.','Ce chapitre est une intention créative : faire vivre la passion dans un nouvel espace numérique. Le design, le code et les histoires de supporters deviennent une autre façon de transmettre les couleurs.'],ar:['الباقي\nنكتبه معاً.','هذا الفصل نية إبداعية: إحياء الشغف في فضاء رقمي جديد. التصميم والبرمجة وحكايات الجماهير طرق أخرى لنقل الألوان.']}
};
function renderEra(){if(!$('#era-title'))return;$('#era-number').textContent=eras[era].number;$('#era-title').textContent=eras[era][lang][0];$('#era-copy').textContent=eras[era][lang][1];}
$$('[data-era]').forEach(b=>b.addEventListener('click',()=>{era=b.dataset.era;selectButtons('[data-era]',b);renderEra();}));

const formations={433:[[50,91],[14,72],[38,76],[62,76],[86,72],[25,48],[50,55],[75,48],[16,21],[50,15],[84,21]],442:[[50,91],[14,73],[38,77],[62,77],[86,73],[14,45],[38,51],[62,51],[86,45],[35,18],[65,18]],352:[[50,91],[24,76],[50,80],[76,76],[9,45],[30,54],[50,44],[70,54],[91,45],[35,18],[65,18]]};
let lineup={formation:'433',names:Array(11).fill('')},selected=0;
try{const saved=JSON.parse(storage.get('dima-mas-lineup'));if(saved&&formations[saved.formation]&&Array.isArray(saved.names)){lineup={formation:saved.formation,names:Array.from({length:11},(_,i)=>typeof saved.names[i]==='string'?saved.names[i].slice(0,18):'')};}}catch{}
function renderPlayers(){if(!$('#players'))return;$('#players').replaceChildren();formations[lineup.formation].forEach(([x,y],i)=>{const b=node('button','player'+(i===selected?' active':''));b.style.left=`${x}%`;b.style.top=`${y}%`;b.setAttribute('aria-pressed',String(i===selected));b.setAttribute('aria-label',words(`Poste ${i+1}, ${lineup.names[i]||'choisir un joueur'}`,`المركز ${i+1}، ${lineup.names[i]||'اختر لاعباً'}`));b.append(node('b','',i+1),node('span','',lineup.names[i]||words(i===0?'GARDIEN':`JOUEUR ${i+1}`,i===0?'حارس':`لاعب ${i+1}`)));b.addEventListener('click',()=>{selected=i;renderPlayers();$('#player-name').value=lineup.names[i];$('#selected-position').textContent=i+1;$('#player-name').focus({preventScroll:true});});$('#players').append(b);});selectButtons('[data-formation]', $(`[data-formation="${lineup.formation}"]`));}
$$('[data-formation]').forEach(b=>b.addEventListener('click',()=>{lineup.formation=b.dataset.formation;renderPlayers();storage.set('dima-mas-lineup',JSON.stringify(lineup));}));
$('#player-form')?.addEventListener('submit',e=>{e.preventDefault();lineup.names[selected]=$('#player-name').value.trim().slice(0,18);renderPlayers();storage.set('dima-mas-lineup',JSON.stringify(lineup));});
$('#reset-lineup')?.addEventListener('click',()=>{lineup={formation:'433',names:Array(11).fill('')};selected=0;$('#player-name').value='';$('#selected-position').textContent='1';renderPlayers();storage.set('dima-mas-lineup',JSON.stringify(lineup));});

let fans=[];
try{const data=JSON.parse(storage.get('dima-mas-fans'));if(Array.isArray(data))fans=data.filter(f=>typeof f?.name==='string'&&typeof f?.message==='string').slice(0,12).map(f=>({name:f.name.slice(0,24),message:f.message.slice(0,180)}));}catch{}
const examples=[{fr:['MASSAWI / FÈS','Les saisons passent. Les couleurs restent.'],ar:['مصاوي / فاس','تمرّ المواسم وتبقى الألوان.']},{fr:['UNE VOIX / LA TRIBUNE','Une ville dans le cœur. Dima MAS.'],ar:['صوت / المدرج','مدينة في القلب. ديما ماص.']},{fr:['FÈS / PARTOUT','Même loin de Fès, le jaune et le noir voyagent avec nous.'],ar:['فاس / في كل مكان','حتى بعيداً عن فاس، يسافر معنا الأصفر والأسود.']}];
function renderFans(){if(!$('#fan-cards'))return;const list=$('#fan-cards');list.replaceChildren();[...fans.map((f,i)=>({...f,local:true,index:i})),...examples.map(f=>({name:f[lang][0],message:f[lang][1]}))].forEach(f=>{const card=node('article','fan-note');card.append(node('span','',words(f.local?'TON MESSAGE · LOCAL':'EXEMPLE ÉDITORIAL',f.local?'رسالتك · محلي':'مثال تحريري')),node('p','',f.message),node('b','',f.name));if(f.local){const del=node('button','delete-note',words('SUPPRIMER','حذف'));del.setAttribute('aria-label',words(`Supprimer le message de ${f.name}`,`احذف رسالة ${f.name}`));del.addEventListener('click',()=>{fans.splice(f.index,1);storage.set('dima-mas-fans',JSON.stringify(fans));renderFans();});card.append(del);}list.append(card);});}
$('#fan-form')?.addEventListener('submit',e=>{e.preventDefault();const name=$('#fan-name').value.trim().slice(0,24),message=$('#fan-message').value.trim().slice(0,180);if(!name||!message){$('#fan-status').textContent=words('Ajoute un nom et quelques mots.','أضف اسماً وبعض الكلمات.');return;}if(fans.length>=12){$('#fan-status').textContent=words('Ton mur contient 12 messages. Supprime-en un pour en ajouter un nouveau.','حائطك يحتوي على 12 رسالة. احذف واحدة لإضافة رسالة جديدة.');return;}fans.unshift({name,message});const saved=storage.set('dima-mas-fans',JSON.stringify(fans));$('#fan-form').reset();renderFans();$('#fan-status').textContent=saved?words('Ajouté à ton mur personnel. Rien n’a été publié.','أُضيفت إلى حائطك الشخصي. لم يُنشر شيء.'):words('Ajouté pour cette visite. Le stockage du navigateur est indisponible.','أُضيفت لهذه الزيارة. تخزين المتصفح غير متاح.');});

$$('[data-poster]').forEach(b=>b.addEventListener('click',()=>{poster=b.dataset.poster;selectButtons('[data-poster]',b);$('#fan-poster').dataset.colour=poster;}));
function download(blob,name){const url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
$('#download-poster')?.addEventListener('click',()=>{const c=document.createElement('canvas');c.width=1440;c.height=1920;const x=c.getContext('2d'),bg=poster==='gold'?'#f2cb25':'#17220e',fg=poster==='gold'?'#17220e':'#f2cb25';x.fillStyle=bg;x.fillRect(0,0,1440,1920);x.strokeStyle=fg;x.globalAlpha=.08;x.lineWidth=3;for(let i=-1920;i<1440;i+=75){x.beginPath();x.moveTo(i,0);x.lineTo(i+1920,1920);x.stroke();}x.globalAlpha=1;x.fillStyle=fg;x.font='24px Arial';x.fillText('FÈS / MAROC',110,140);x.font='570px Impact, Arial Narrow, sans-serif';x.fillText('DIMA',90,770,1280);x.fillText('MAS.',90,1270,1280);x.font='bold 100px Arial';x.direction='rtl';x.textAlign='right';x.fillText('فاس في القلب',1320,1580);x.direction='ltr';x.textAlign='left';x.font='21px Arial';x.fillText('DIMA MAS / INDEPENDENT FAN CONCEPT / 1946',110,1810);x.strokeStyle=fg;x.globalAlpha=.5;x.lineWidth=2;x.strokeRect(65,65,1310,1790);c.toBlob(blob=>{if(blob)download(blob,`dima-mas-affiche-${poster}.png`);},'image/png');});

const stories={city:{fr:['FÈS, COMME POINT DE DÉPART.','Les tons chauds des murs, les répétitions du zellige, l’ombre des ruelles : ce projet traduit une inspiration urbaine en langage graphique. Les motifs du maillot sont une interprétation originale, et non la copie d’un objet patrimonial précis.','Le visuel de Fès a été généré par IA pour donner une atmosphère au concept. Il ne documente pas un lieu ou un événement exact.'],ar:['فاس، نقطة البداية.','دفء الجدران وتكرار الزليج وظلال الأزقة: يحوّل هذا المشروع الإلهام الحضري إلى لغة بصرية. أنماط القميص تفسير أصلي، وليست نسخاً لقطعة تراثية بعينها.','صورة فاس مولّدة بالذكاء الاصطناعي لتعطي أجواء للفكرة، ولا توثّق مكاناً أو حدثاً محدداً.']},colours:{fr:['LE JAUNE ET LE NOIR, EN MOUVEMENT.','Cette expérience utilise le jaune comme un appel : un titre, un drapeau, un détail qui capte l’œil. Le noir lui donne de la profondeur. Ensemble, les deux couleurs relient toutes les pages.','Les emblèmes, maillots et affiches sont des créations indépendantes pour ce portfolio. Ils ne sont pas des produits officiels du club.'],ar:['الأصفر والأسود، في حركة.','يستعمل هذا المشروع الأصفر كنداء: عنوان وعلم وتفصيل يجذب العين. الأسود يعطيه عمقاً. معاً يربط اللونان كل الصفحات.','الشعارات والقمصان والملصقات إبداعات مستقلة لملف الأعمال. ليست منتجات رسمية للنادي.']},digital:{fr:['UNE PASSION À EXPLORER.','Le ballon tourne, le stade change de lumière et les drapeaux ondulent. Chaque scène est dessinée en trois dimensions et réagit à tes gestes. Le studio transforme ensuite cette exploration en création personnelle.','Ce projet est une vitrine de développement web : 3D interactive, navigation multi-page, interface français / arabe, panier local et téléchargements. Les données de matchs et les prix restent fictifs.'],ar:['شغف للاستكشاف.','تدور الكرة ويتغيّر ضوء الملعب وتتموّج الأعلام. كل مشهد ثلاثي الأبعاد يستجيب لحركاتك. ثم يحوّل الاستوديو الاستكشاف إلى إبداع شخصي.','هذا المشروع عرض لتطوير الويب: رسوم تفاعلية وتنقّل متعدد الصفحات وواجهة فرنسية وعربية وسلة محلية وتنزيلات. المباريات والأسعار خيالية.']}};
$$('[data-story]').forEach(b=>b.addEventListener('click',()=>{const content=stories[b.dataset.story][lang],dialog=$('#info-dialog');$('#info-kicker').textContent=words('LE JOURNAL DU CONCEPT','يوميات الفكرة');$('#info-title').textContent=content[0];$('#info-body').replaceChildren(...content.slice(1).map(p=>node('p','',p)));dialog.showModal();document.body.style.overflow='hidden';dialog.addEventListener('close',()=>b.focus({preventScroll:true}),{once:true});}));
translate();
